import (
	"context"
	"errors"
	"fmt"
	"net"
	"net/http"
	"time"
)

var ErrBlockedPrivateIP = errors.New("connection to private/internal IP address blocked by SSRF defense")

func isRestrictedIP(ip net.IP) bool {
	if ip == nil {
		return true
	}
	// Проверка стандартных методов Go 1.17+
	if ip.IsLoopback() || ip.IsPrivate() || ip.IsLinkLocalUnicast() || ip.IsLinkLocalMulticast() || ip.IsUnspecified() {
		return true
	}

	// Дополнительная явная проверка облачных Link-Local метаданных (AWS, GCP, Azure 169.254.169.254)
	cloudMeta := net.ParseIP("169.254.169.254")
	if ip.Equal(cloudMeta) {
		return true
	}

	return false
}

func SafeDialContext() func(ctx context.Context, network, addr string) (net.Conn, error) {
	dialer := &net.Dialer{
		Timeout:   5 * time.Second,
		KeepAlive: 30 * time.Second,
	}

	return func(ctx context.Context, network, addr string) (net.Conn, error) {
		host, port, err := net.SplitHostPort(addr)
		if err != nil {
			return nil, err
		}

		// Резолвим все IP адреса хоста
		ips, err := net.DefaultResolver.LookupIP(ctx, "ip", host)
		if err != nil {
			return nil, fmt.Errorf("dns lookup failed: %w", err)
		}

		if len(ips) == 0 {
			return nil, errors.New("no IP addresses found for host")
		}

		// Проверяем каждый полученный IP адрес
		for _, ip := range ips {
			if isRestrictedIP(ip) {
				return nil, fmt.Errorf("%w: %s resolves to %s", ErrBlockedPrivateIP, host, ip.String())
			}
		}

		// Подключаемся напрямую к первому проверенному публичному IP адресу,
		// чтобы предотвратить DNS Rebinding при повторном dial
		targetAddr := net.JoinHostPort(ips[0].String(), port)
		return dialer.DialContext(ctx, network, targetAddr)
	}
}

func NewSafeHTTPClient() *http.Client {
	transport := &http.Transport{
		DialContext:           SafeDialContext(),
		TLSHandshakeTimeout:   5 * time.Second,
		ResponseHeaderTimeout: 5 * time.Second,
		ExpectContinueTimeout: 1 * time.Second,
		DisableKeepAlives:     true, // Защита от reuse сокета при смене хоста
	}

	return &http.Client{
		Transport: transport,
		Timeout:   10 * time.Second,
		CheckRedirect: func(req *http.Request, via []*http.Request) error {
			if len(via) >= 5 {
				return errors.New("too many redirects")
			}
			return nil // Кастомный транспорт проверит адрес редиректа автоматически в DialContext!
		},
	}
}

func main() {
	client := NewSafeHTTPClient()

	testTargets := []string{
		"http://127.0.0.1:8080/admin",
		"http://localhost:6379",
		"http://169.254.169.254/latest/meta-data/",
		"http://192.168.1.1/router-login",
		"http://10.0.0.5/internal-api",
	}

	for _, target := range testTargets {
		fmt.Println("Requesting:", target)
		_, err := client.Get(target)
		if err != nil {
			fmt.Println("Blocked:", err)
		} else {
			fmt.Println("Allowed (VULNERABLE!)")
		}
		fmt.Println(strings.Repeat("-", 60))
	}
}

