import (
	"context"
	"errors"
	"fmt"
	"net"
	"net/http"
	"net/url"
	"strings"
	"time"
)

type SSRFPolicy struct {
	AllowedHosts map[string]struct{}
	RequireHTTPS bool
}

func (p *SSRFPolicy) ValidateURL(u *url.URL) error {
	if p.RequireHTTPS && u.Scheme != "https" {
		return fmt.Errorf("insecure scheme '%s': only https is allowed", u.Scheme)
	}
	if u.Scheme != "http" && u.Scheme != "https" {
		return fmt.Errorf("unsupported scheme: %s", u.Scheme)
	}

	hostname := strings.ToLower(u.Hostname())
	if len(p.AllowedHosts) > 0 {
		if _, ok := p.AllowedHosts[hostname]; !ok {
			return fmt.Errorf("host '%s' is not in allowed domains whitelist", hostname)
		}
	}
	return nil
}

func isForbiddenIP(ip net.IP) bool {
	if ip == nil {
		return true
	}
	if ip.IsLoopback() || ip.IsPrivate() || ip.IsLinkLocalUnicast() || ip.IsLinkLocalMulticast() || ip.IsUnspecified() {
		return true
	}
	// AWS / GCP / Azure Link-Local Metadata (169.254.169.254)
	if ip.Equal(net.ParseIP("169.254.169.254")) {
		return true
	}
	return false
}

func NewHardenedClient(policy SSRFPolicy) *http.Client {
	transport := &http.Transport{
		DialContext: func(ctx context.Context, network, addr string) (net.Conn, error) {
			host, port, err := net.SplitHostPort(addr)
			if err != nil {
				return nil, err
			}

			ips, err := net.DefaultResolver.LookupIP(ctx, "ip", host)
			if err != nil {
				return nil, fmt.Errorf("dns lookup error: %w", err)
			}

			if len(ips) == 0 {
				return nil, errors.New("no IPs resolved")
			}

			for _, ip := range ips {
				if isForbiddenIP(ip) {
					return nil, fmt.Errorf("security violation: IP %s is restricted", ip.String())
				}
			}

			dialer := &net.Dialer{Timeout: 3 * time.Second}
			// Пиннинг проверенного IP адреса:
			pinnedAddr := net.JoinHostPort(ips[0].String(), port)
			return dialer.DialContext(ctx, network, pinnedAddr)
		},
		TLSHandshakeTimeout: 3 * time.Second,
		DisableKeepAlives:   true,
	}

	return &http.Client{
		Transport: transport,
		Timeout:   5 * time.Second,
		CheckRedirect: func(req *http.Request, via []*http.Request) error {
			if len(via) >= 3 {
				return errors.New("too many redirects (max 3)")
			}
			// Проверяем целевой URL редиректа по общей политике
			if err := policy.ValidateURL(req.URL); err != nil {
				return fmt.Errorf("redirect blocked: %w", err)
			}
			return nil
		},
	}
}

func main() {
	policy := SSRFPolicy{
		AllowedHosts: map[string]struct{}{
			"api.partner.com": {},
			"cdn.company.com": {},
		},
		RequireHTTPS: true,
	}

	client := NewHardenedClient(policy)

	testCases := []string{
		"http://api.partner.com/data",               // Ошибка: не HTTPS
		"https://evil.com/leak",                     // Ошибка: нет в whitelist
		"https://api.partner.com/user",              // Валидный (пройдет проверку схемы и домена)
		"file:///etc/passwd",                        // Ошибка: схема file
		"http://169.254.169.254/latest/meta-data/",  // Ошибка: схема и IP
	}

	fmt.Println("=== ТЕСТИРОВАНИЕ КОМПЛЕКСНОЙ SSRF ЗАЩИТЫ ===")
	for _, target := range testCases {
		u, err := url.Parse(target)
		if err != nil {
			fmt.Println("Invalid URL:", target)
			continue
		}

		err = policy.ValidateURL(u)
		if err != nil {
			fmt.Printf("URL: %-42s -> BLOCKED at Policy Check: %v\n", target, err)
			continue
		}

		// Выполняем запрос через защищенный транспорт
		_, err = client.Get(target)
		if err != nil {
			fmt.Printf("URL: %-42s -> BLOCKED at Transport: %v\n", target, err)
		} else {
			fmt.Printf("URL: %-42s -> ALLOWED\n", target)
		}
	}
}

