import (
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

var ErrPathTraversal = errors.New("access denied: path traversal attempt detected")

// SafeFilePath проверяет, что целевой файл строго лежит внутри baseDir
func SafeFilePath(baseDir, userFilename string) (string, error) {
	// 1. Получаем абсолютный канонический путь базовой папки
	absBase, err := filepath.Abs(baseDir)
	if err != nil {
		return "", err
	}

	// 2. Очищаем путь пользователя и соединяем с базой
	cleanInput := filepath.Clean(userFilename)
	fullPath := filepath.Join(absBase, cleanInput)

	// 3. Получаем абсолютный путь к целевому файлу
	absTarget, err := filepath.Abs(fullPath)
	if err != nil {
		return "", err
	}

	// 4. Вычисляем относительный путь от базовой директории до цели
	rel, err := filepath.Rel(absBase, absTarget)
	if err != nil {
		return "", ErrPathTraversal
	}

	// Если относительный путь начинается с '..' или ведет наружу — это атака!
	if strings.HasPrefix(rel, "..") || rel == ".." {
		return "", fmt.Errorf("%w: target %s is outside base %s", ErrPathTraversal, absTarget, absBase)
	}

	return absTarget, nil
}

func main() {
	tempBase, err := os.MkdirTemp("", "safe_storage_*")
	if err != nil {
		panic(err)
	}
	defer os.RemoveAll(tempBase)

	// Создаем легитимный файл
	legitFile := filepath.Join(tempBase, "avatar.png")
	_ = os.WriteFile(legitFile, []byte("fake-png-data"), 0644)

	attackPayloads := []string{
		"avatar.png",                           // Легитимный файл
		"../../../etc/passwd",                  // Классический traversal
		"subfolder/../../../../etc/shadow",     // Обход через подпапку
		"..\\..\\windows\\win.ini",             // Windows-style слэши
		"/etc/passwd",                          // Абсолютный путь
		"avatar.png/../../../secret.env",       // Traversal в имени
	}

	fmt.Println("Base Storage Directory:", tempBase)
	fmt.Println(strings.Repeat("-", 70))

	for _, payload := range attackPayloads {
		safePath, err := SafeFilePath(tempBase, payload)
		if err != nil {
			fmt.Printf("Input: %-36s -> 🛡️ BLOCKED: %v\n", payload, err)
		} else {
			fmt.Printf("Input: %-36s -> ✅ ALLOWED: %s\n", payload, safePath)
		}
	}
}

package main

import (
	"fmt"
	"net/http"
	"net/http/httptest"
	"net/url"
	"strings"
)

var trustedDomains = map[string]bool{
	"app.company.com":     true,
	"support.company.com": true,
}

func SafeRedirectTarget(rawTarget string, fallback string) string {
	if strings.TrimSpace(rawTarget) == "" {
		return fallback
	}

	// Защита от protocol-relative bypass: //evil.com или /\evil.com
	if strings.HasPrefix(rawTarget, "//") || strings.HasPrefix(rawTarget, "/\\") || strings.HasPrefix(rawTarget, "\\") {
		return fallback
	}

	u, err := url.Parse(rawTarget)
	if err != nil {
		return fallback
	}

	// 1. Относительный путь в рамках текущего домена (Safe Relative URL)
	if u.Scheme == "" && u.Host == "" {
		if strings.HasPrefix(u.Path, "/") {
			// Возвращаем Path с сохранением Query параметров
			return u.RequestURI()
		}
		return fallback
	}

	// 2. Внешний абсолютный URL: только HTTPS и строгий whitelist хостов
	if u.Scheme != "https" {
		return fallback
	}

	hostname := strings.ToLower(u.Hostname())
	if trustedDomains[hostname] {
		return u.String()
	}

	return fallback
}

func AuthCallbackHandler(w http.ResponseWriter, r *http.Request) {
	redirectParam := r.URL.Query().Get("redirect")
	target := SafeRedirectTarget(redirectParam, "/home")
	http.Redirect(w, r, target, http.StatusFound)
}

func main() {
	tests := []struct {
		name     string
		param    string
		expected string
	}{
		{"Legitimate Relative", "/settings/profile?tab=security", "/settings/profile?tab=security"},
		{"Legitimate External Whitelist", "https://app.company.com/workspace", "https://app.company.com/workspace"},
		{"Phishing Evil Domain", "https://evil-bank.com/steal", "/home"},
		{"Protocol Relative Trick", "//evil-bank.com", "/home"},
		{"Backslash Trick", "/\\evil-bank.com", "/home"},
		{"Javascript URI", "javascript:alert(document.cookie)", "/home"},
		{"Subdomain Spoofing", "https://app.company.com.evil.com/page", "/home"},
	}

	for _, tt := range tests {
		req := httptest.NewRequest(http.MethodGet, "/login?redirect="+url.QueryEscape(tt.param), nil)
		rec := httptest.NewRecorder()
		AuthCallbackHandler(rec, req)

		location := rec.Header().Get("Location")
		success := location == tt.expected
		fmt.Printf("[Test: %-28s] Target: %-32s -> Location: %-26s | Passed: %v\n",
			tt.name, tt.param, location, success)
	}
}

