import (
	"context"
	"errors"
	"fmt"
	"net"
	"net/http"
	"strings"
	"time"
)

var restrictedCIDRs []*net.IPNet

func init() {
	rawCIDRs := []string{
		"127.0.0.0/8",    // IPv4 loopback
		"10.0.0.0/8",     // RFC 1918 private
		"172.16.0.0/12",  // RFC 1918 private
		"192.168.0.0/16", // RFC 1918 private
		"169.254.0.0/16", // Link-Local (Cloud metadata)
		"0.0.0.0/8",      // Current network
		"100.64.0.0/10",  // Carrier-grade NAT
		"::1/128",        // IPv6 loopback
		"fc00::/7",       // IPv6 Unique local
		"fe80::/10",      // IPv6 Link-local
	}

	for _, cidr := range rawCIDRs {
		_, ipNet, err := net.ParseCIDR(cidr)
		if err != nil {
			panic(err)
		}
		restrictedCIDRs = append(restrictedCIDRs, ipNet)
	}
}

func IsIPRestricted(ip net.IP) bool {
	if ip == nil {
		return true
	}
	for _, cidr := range restrictedCIDRs {
		if cidr.Contains(ip) {
			return true
		}
	}
	return false
}

func NewSSRFSafeTransport() *http.Transport {
	return &http.Transport{
		DialContext: func(ctx context.Context, network, addr string) (net.Conn, error) {
			host, port, err := net.SplitHostPort(addr)
			if err != nil {
				return nil, err
			}

			ips, err := net.DefaultResolver.LookupIP(ctx, "ip", host)
			if err != nil {
				return nil, fmt.Errorf("SSRF: dns resolution failed for %s: %w", host, err)
			}

			if len(ips) == 0 {
				return nil, errors.New("SSRF: no IP addresses resolved")
			}

			// Проверяем все IP адреса, возвращенные DNS
			for _, ip := range ips {
				if IsIPRestricted(ip) {
					return nil, fmt.Errorf("SSRF blocked: host %s resolved to restricted IP %s", host, ip.String())
				}
			}

			// Пиннинг: подключаемся к первому проверенному публичному IP
			dialer := &net.Dialer{Timeout: 3 * time.Second}
			safeAddr := net.JoinHostPort(ips[0].String(), port)
			return dialer.DialContext(ctx, network, safeAddr)
		},
		TLSHandshakeTimeout: 3 * time.Second,
		DisableKeepAlives:   true,
	}
}

func main() {
	client := &http.Client{
		Transport: NewSSRFSafeTransport(),
		Timeout:   5 * time.Second,
	}

	testTargets := []string{
		"http://127.0.0.1:8080/metrics",
		"http://10.0.1.50/db-admin",
		"http://169.254.169.254/latest/meta-data/",
		"http://192.168.1.1/admin",
		"http://0.0.0.0:3000/",
	}

	fmt.Println("=== ТЕСТИРОВАНИЕ SSRF БЛОКИРОВЩИКА ПОДСЕТЕЙ ===")
	for _, target := range testTargets {
		_, err := client.Get(target)
		if err != nil {
			fmt.Printf("Target: %-42s -> 🛡️ BLOCKED:\n  %v\n", target, err)
		} else {
			fmt.Printf("Target: %-42s -> ⚠️ VULNERABLE!\n", target)
		}
	}
}

